INSERT OR IGNORE INTO sys_notice (notice_id, notice_title, notice_type, notice_content, status, create_by) VALUES (2, '新版功能上线公告', '2', '本次更新正式上线以下功能：1、订单管理（支持订单明细查看与增删改查）；2、代码生成（一键生成前后端 CRUD 代码）；3、消息通知（支持公告发布与查看）。欢迎大家体验并反馈意见。', '0', 'admin');
INSERT OR IGNORE INTO sys_notice (notice_id, notice_title, notice_type, notice_content, status, create_by) VALUES (3, '信息安全规范通知', '1', '请各位用户妥善保管账号密码，定期修改登录密码，不要将账号借给他人使用。系统将记录所有登录与操作日志，请注意合规操作。', '0', 'admin');
